def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
prev=json.loads((R/'qa/field_geometry006_review.json').read_text('utf8'));assert sha(R/'qa/field_sr_catalog.json')==prev['catalog_after_sha256'];assert sha(R/'qa/architectural_geometry_contract.json')==prev['geometry_contract_after_sha256'];inv=json.loads((R/'qa/field_map_inventory_v2.json').read_text('utf8'));assert sha(R/'qa/field_map_inventory_v2.json')==prev['protected_file_hashes']['qa/field_map_inventory_v2.json'];tex={v['id']:v for v in inv['textures']};priors=[R/f'qa/field_source_review0{i}.json' for i in (1,2,3)];done={v['group_id'] for p in priors for v in json.loads(p.read_text('utf8'))['files']};groups=[g for g in inv['groups'] if not g['battle_pixel_equivalent_group'] and g['group_id'] not in done];assert len(done)==216 and len(groups)==135
